def support_form():
    lang = get_lang()
    return page(t("web.nav.support", lang), f"""<div class="card"><h2>{t("web.support.title", lang)}</h2>
    <form method="post">
    <label>{t("web.support.sev", lang)}</label><select name="sev">
      <option value="urgent">{t("support.urgent", lang)}</option>
